import{_ as e,o as r,c as a,a2 as d}from"./chunks/framework.il0noOp3.js";const A=JSON.parse('{"title":"WAF — enumerated source for the Azure AI Search technology review","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/waf-ai-search-checklist.md","filePath":"frameworks/waf-ai-search-checklist.md"}'),i={name:"frameworks/waf-ai-search-checklist.md"};function o(s,t,n,c,l,h){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="waf-—-enumerated-source-for-the-azure-ai-search-technology-review" tabindex="-1">WAF — enumerated source for the Azure AI Search technology review <a class="header-anchor" href="#waf-—-enumerated-source-for-the-azure-ai-search-technology-review" aria-label="Permalink to &quot;WAF — enumerated source for the Azure AI Search technology review&quot;">​</a></h1><p><strong>Enumerated 2026-11-25. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><p>Scout&#39;s <code>waf.aisearch.yaml</code> scores the Azure AI Search review. Microsoft publishes no Well-Architected service guide for this service, so this page enumerates the current product guidance that covers the same ground, item by item. The rule file is written against this page only; every rule cites an item number from the tables below.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Assessment</td><td><a href="https://learn.microsoft.com/en-us/assessments/783533b2-403a-4985-8c60-97db4910f741/" target="_blank" rel="noreferrer">Azure Cognitive Search — Well-Architected Review</a> (30 minutes, multiple choice and multiple response; question text not published; page still uses the old product name)</td></tr><tr><td>Framework version</td><td>Azure AI Search (Foundry IQ) product documentation on Microsoft Learn, current at extraction; ARM Microsoft.Search searchServices latest API 2026-11-01</td></tr><tr><td>Extraction date</td><td>2026-11-25</td></tr><tr><td>Verification method</td><td>The Well-Architected service-guide catalog was fetched on 2026-11-25 and has no Azure AI Search entry. The reliability, security best-practices, performance-tips and cost articles named below were fetched in full with the Microsoft Learn MCP <code>microsoft_docs_fetch</code> tool the same day, and the searchServices ARM template reference was read to confirm the properties the automated items use (replicaCount, publicNetworkAccess, disableLocalAuth, sku, computeType, encryptionWithCmk, networkRuleSet, semanticSearch, upgradeAvailable).</td></tr></tbody></table><h2 id="the-one-thing-this-enumeration-is-not" tabindex="-1">The one thing this enumeration is NOT <a class="header-anchor" href="#the-one-thing-this-enumeration-is-not" aria-label="Permalink to &quot;The one thing this enumeration is NOT&quot;">​</a></h2><p><strong>It is not Microsoft&#39;s question list, and there is no Microsoft Well-Architected checklist for this service.</strong> The items below are <strong>Scout&#39;s</strong> reading of the product articles and the <code>WAF-AISEARCH-*</code> ids are Scout&#39;s. Where the product article is the only source, the source code says so.</p><p>Sources (the code after each item names the page and section; -C is a workload design checklist bullet, -R a configuration recommendations row):</p><ul><li>[ARCH] <a href="https://learn.microsoft.com/azure/architecture/ai-ml/architecture/search-blob-metadata" target="_blank" rel="noreferrer">Create an Azure AI Search index based on file content and metadata</a> (Well-Architected considerations: replicas and SLA)</li><li>[COST] <a href="https://learn.microsoft.com/azure/search/search-sku-manage-costs" target="_blank" rel="noreferrer">Plan and manage costs</a></li><li>[PERF] <a href="https://learn.microsoft.com/azure/search/search-performance-tips" target="_blank" rel="noreferrer">Tips for better performance</a></li><li>[REL] <a href="https://learn.microsoft.com/azure/search/search-reliability" target="_blank" rel="noreferrer">Reliability in Foundry IQ (Azure AI Search)</a></li><li>[SEC] <a href="https://learn.microsoft.com/azure/search/search-security-best-practices" target="_blank" rel="noreferrer">Secure a Foundry IQ (Azure AI Search) service</a></li></ul><p>The service is documented as Foundry IQ (Azure AI Search) and offers Dedicated and Serverless pricing models. The Serverless model has no replica or partition count, so replica rules skip <code>sku = serverless</code>. The older <code>waf.ai</code> rule set also scores search services (WAF-AI-DATA-07 and -08); this review is separate and does not replace it.</p><h2 id="the-enumeration-—-37-items" tabindex="-1">The enumeration — 37 items <a class="header-anchor" href="#the-enumeration-—-37-items" aria-label="Permalink to &quot;The enumeration — 37 items&quot;">​</a></h2><h3 id="reliability-waf-aisearch-re-—-10-items" tabindex="-1">Reliability (WAF-AISEARCH-RE) — 10 items <a class="header-anchor" href="#reliability-waf-aisearch-re-—-10-items" aria-label="Permalink to &quot;Reliability (WAF-AISEARCH-RE) — 10 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-AISEARCH-RE-01</td><td>The service is on a billable tier (not Free)</td><td>✅ service sku</td><td>REL</td></tr><tr><td>WAF-AISEARCH-RE-02</td><td>Dedicated services have at least two replicas</td><td>✅ replicaCount below 2 on a billable dedicated tier</td><td>REL, ARCH</td></tr><tr><td>WAF-AISEARCH-RE-03</td><td>Services that update indexes have at least three replicas</td><td>❌ Manual — whether a workload writes to the index is not collected; services below three replicas attached</td><td>REL</td></tr><tr><td>WAF-AISEARCH-RE-04</td><td>The service is in a region that supports availability zones</td><td>❌ Manual — region support list is not collected; services attached with region</td><td>REL</td></tr><tr><td>WAF-AISEARCH-RE-05</td><td>A multi-region approach exists for regional failure</td><td>❌ Manual — architecture judgement; services attached</td><td>REL</td></tr><tr><td>WAF-AISEARCH-RE-06</td><td>The index can be rebuilt or restored from source data</td><td>❌ Manual — data-plane recovery, not ARM</td><td>REL</td></tr><tr><td>WAF-AISEARCH-RE-07</td><td>A delete lock protects the search service</td><td>❌ Manual — resource locks attached</td><td>REL, SEC</td></tr><tr><td>WAF-AISEARCH-RE-08</td><td>Clients retry transient faults with exponential backoff</td><td>❌ Manual — client code, not ARM</td><td>REL</td></tr><tr><td>WAF-AISEARCH-RE-09</td><td>Resource Health and Service Health alerts are configured</td><td>❌ Manual — activity-log alert rules attached (estate-wide)</td><td>REL</td></tr><tr><td>WAF-AISEARCH-RE-10</td><td>Dependencies of indexers, skills and vectorizers are reliable</td><td>❌ Manual — dependency review, not ARM</td><td>REL</td></tr></tbody></table><h3 id="security-waf-aisearch-se-—-11-items" tabindex="-1">Security (WAF-AISEARCH-SE) — 11 items <a class="header-anchor" href="#security-waf-aisearch-se-—-11-items" aria-label="Permalink to &quot;Security (WAF-AISEARCH-SE) — 11 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-AISEARCH-SE-01</td><td>Inbound public network access is disabled</td><td>✅ publicNetworkAccess</td><td>SEC</td></tr><tr><td>WAF-AISEARCH-SE-02</td><td>Each search service has a private endpoint</td><td>✅ search service to private endpoint join</td><td>SEC</td></tr><tr><td>WAF-AISEARCH-SE-03</td><td>API-key authentication is disabled in favour of Microsoft Entra role-based access</td><td>✅ disableLocalAuth</td><td>SEC</td></tr><tr><td>WAF-AISEARCH-SE-04</td><td>The service has a managed identity for outbound connections</td><td>❌ Manual — the identity type is not collected (proposed projection in the report); services attached</td><td>SEC</td></tr><tr><td>WAF-AISEARCH-SE-05</td><td>Outbound connections to protected data use shared private links, a trusted-service exception or firewall exceptions</td><td>❌ Manual — shared private links are child resources, not collected</td><td>SEC</td></tr><tr><td>WAF-AISEARCH-SE-06</td><td>Customer-managed key encryption is used where required</td><td>❌ Manual — encryptionWithCmk is not collected (proposed projection in the report); services attached</td><td>SEC</td></tr><tr><td>WAF-AISEARCH-SE-07</td><td>Confidential compute is used only where regulation requires it</td><td>❌ Manual — computeType is not collected (proposed projection in the report); services attached</td><td>SEC</td></tr><tr><td>WAF-AISEARCH-SE-08</td><td>Document-level access control or security filters trim results per caller</td><td>❌ Manual — data-plane design, not ARM</td><td>SEC</td></tr><tr><td>WAF-AISEARCH-SE-09</td><td>Access to individual indexes follows least privilege</td><td>❌ Manual — role design, not collected per service</td><td>SEC</td></tr><tr><td>WAF-AISEARCH-SE-10</td><td>Diagnostic logging is on and alerts watch for anomalous activity</td><td>❌ Manual — type not yet in the diagnostic-settings sweep (proposed in the report)</td><td>SEC</td></tr><tr><td>WAF-AISEARCH-SE-11</td><td>An IP firewall or network security perimeter limits inbound access when public access stays on</td><td>❌ Manual — the IP rule set is not collected (proposed projection in the report); services with public access attached</td><td>SEC</td></tr></tbody></table><h3 id="cost-optimization-waf-aisearch-co-—-7-items" tabindex="-1">Cost optimization (WAF-AISEARCH-CO) — 7 items <a class="header-anchor" href="#cost-optimization-waf-aisearch-co-—-7-items" aria-label="Permalink to &quot;Cost optimization (WAF-AISEARCH-CO) — 7 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-AISEARCH-CO-01</td><td>The pricing model and tier are the lightest that meet the need</td><td>❌ Manual — workload shape is judgement; services attached</td><td>COST</td></tr><tr><td>WAF-AISEARCH-CO-02</td><td>Replicas and partitions are added only when index size, throughput or availability needs them</td><td>❌ Manual — utilisation is not collected; services attached</td><td>COST</td></tr><tr><td>WAF-AISEARCH-CO-03</td><td>Higher tiers are weighed against more partitions or replicas of a lower tier</td><td>❌ Manual — services attached</td><td>PERF, COST</td></tr><tr><td>WAF-AISEARCH-CO-04</td><td>Related resources are in the same region</td><td>❌ Manual — regions attached; related resources are not linked</td><td>COST</td></tr><tr><td>WAF-AISEARCH-CO-05</td><td>Incremental indexing, an enrichment cache and a knowledge store limit repeated enrichment cost</td><td>❌ Manual — indexer configuration, not collected</td><td>COST</td></tr><tr><td>WAF-AISEARCH-CO-06</td><td>Semantic ranker and agentic retrieval plans are set deliberately</td><td>❌ Manual — the semanticSearch plan is not collected (proposed projection in the report); services attached</td><td>COST</td></tr><tr><td>WAF-AISEARCH-CO-07</td><td>Budgets and cost alerts exist for the workload</td><td>❌ Manual — budgets attached (estate-wide)</td><td>COST</td></tr></tbody></table><h3 id="operational-excellence-waf-aisearch-oe-—-5-items" tabindex="-1">Operational excellence (WAF-AISEARCH-OE) — 5 items <a class="header-anchor" href="#operational-excellence-waf-aisearch-oe-—-5-items" aria-label="Permalink to &quot;Operational excellence (WAF-AISEARCH-OE) — 5 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-AISEARCH-OE-01</td><td>Metrics for queries per second, latency, throttling and indexer runs are monitored</td><td>❌ Manual — metric alert rules attached (estate-wide)</td><td>SEC, COST</td></tr><tr><td>WAF-AISEARCH-OE-02</td><td>Services and indexes are deployed as code</td><td>❌ Manual — deployment method is not an ARM property</td><td>SEC</td></tr><tr><td>WAF-AISEARCH-OE-03</td><td>Service upgrades are applied</td><td>❌ Manual — upgradeAvailable is not collected (proposed projection in the report); services attached</td><td>PERF</td></tr><tr><td>WAF-AISEARCH-OE-04</td><td>Azure Policy audits logging and private endpoint use and resources are tagged</td><td>❌ Manual — policy assignment scope, not collected per service</td><td>SEC</td></tr><tr><td>WAF-AISEARCH-OE-05</td><td>Indexes are updated side by side so queries never see half-built data</td><td>❌ Manual — data-plane practice, not ARM</td><td>REL, PERF</td></tr></tbody></table><h3 id="performance-efficiency-waf-aisearch-pe-—-4-items" tabindex="-1">Performance efficiency (WAF-AISEARCH-PE) — 4 items <a class="header-anchor" href="#performance-efficiency-waf-aisearch-pe-—-4-items" aria-label="Permalink to &quot;Performance efficiency (WAF-AISEARCH-PE) — 4 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-AISEARCH-PE-01</td><td>Index schema attributes are selective</td><td>❌ Manual — index definitions are data plane, not collected</td><td>PERF</td></tr><tr><td>WAF-AISEARCH-PE-02</td><td>Queries are designed for performance</td><td>❌ Manual — query code, not ARM</td><td>PERF</td></tr><tr><td>WAF-AISEARCH-PE-03</td><td>Capacity matches load: replicas for query volume, partitions for slow single queries and index size</td><td>❌ Manual — utilisation is not collected; services attached</td><td>PERF</td></tr><tr><td>WAF-AISEARCH-PE-04</td><td>The application, data sources and search service are in the same region</td><td>❌ Manual — regions attached; the application is not linked</td><td>PERF, COST</td></tr></tbody></table><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pillar</th><th>Items</th><th>Automated (✅)</th><th>Manual (❌)</th></tr></thead><tbody><tr><td>Reliability</td><td>10</td><td>2</td><td>8</td></tr><tr><td>Security</td><td>11</td><td>3</td><td>8</td></tr><tr><td>Cost optimization</td><td>7</td><td>0</td><td>7</td></tr><tr><td>Operational excellence</td><td>5</td><td>0</td><td>5</td></tr><tr><td>Performance efficiency</td><td>4</td><td>0</td><td>4</td></tr><tr><td><strong>Total</strong></td><td><strong>37</strong></td><td><strong>5</strong></td><td><strong>32</strong></td></tr></tbody></table><p>Every automated item is gated on its resources (or its diagnostic-coverage rows) existing, so an estate without them reports the item Not assessed. The rules live in <code>src/assess/rules/waf.aisearch.yaml</code>.</p>',24)])])}const p=e(i,[["render",o]]);export{A as __pageData,p as default};
